use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = galley.menu.board();
    var index = 0;
    while index < board.len() {
        if index > 0 {
            io.write(text: ";")?;
        }
        let dish = board.get(index).to_result(error: ??)?;
        galley.kitchen.serve(io: io, dish: dish)?;
        index = index + 1;
    }
    return Ok(unit);
}

