use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var total = 0;
    var frames = relay.feed.frames();

    while !frames.is_empty() {
        let value = match frames.pop() {
            Some(frame) => match relay.feed.try_decode(frame) {
                Ok(value) => value,
                Err(_) => 0,
            },
            None => 0,
        };
        total = total + value;
    }

    relay.feed.emit_total(io: io, total: total)?;
    return Ok(unit);
}

