use mill.stock;
use mill.rules;

pub fn lines() -> String {
    let planks = mill.stock.inventory();
    var labels: List<String> = [];
    var index = 0;
    while index < planks.len() {
        let plank = planks.get(index)?;
        if mill.rules.keep(plank) {
            labels.push(item: mill.rules.label(plank));
        }
        index = index + 1;
    }
    labels.join(sep: ",")
}

