use harbor.signal;

pub fn entries() -> String {
    let signals = harbor.signal.today();
    var rendered: List<String> = [];
    var index = 0;
    while index < signals.len() {
        let signal = match signals.get(index) {
            Some(value) => value,
            None => ??,
        };
        let entry = match signal {
            harbor.signal.Signal.Calm => "calm",
            harbor.signal.Signal.Gale(speed) => "gale:".concat(other: speed.to_text()),
            harbor.signal.Signal.Fog(density) => "fog:".concat(other: density),
        };
        rendered.push(entry);
        index = index + 1;
    }
    rendered.join(sep: ";")
}

